css:
/* ---------- page / print ---------- */
 @page {
     size: A4 portrait;
 }

 * {
     box-sizing: border-box;
     /* border: 1px solid navy; */
 }

 .print-format,
 .print-format-preview {
     display: block !important;
     padding: 0 !important;
     margin: 0 !important;
     background: none !important;
     border: none !important;
     border-radius: 0 !important;
     box-shadow: none !important;
 }

 .print-format td,
 .print-format th {
     padding: 0 !important;
 }

 /* html, body { margin: 0; padding: 0; -webkit-print-color-adjust: exact; print-color-adjust: exact; } */
 /* body { background: #d4d4d4; font-family: Arial, Helvetica, sans-serif; color: #000; } */

 .sheet {
     width: 210mm;
     /*height: 297mm;*/
     height: 310mm;
     
     margin-bottom: 15mm;
     /* background: aqua; */
     padding: 1mm;
     font-size: 9px;
     box-shadow: 0 4px 12px rgba(0, 0, 0, .3);
 }

 .frame {
     border: 1px Solid #000;
     width: 100%;
     height: 100%;
     background: #fff;
     display: flex;
     flex-direction: column;
     /* align-items: center; */
     justify-content: flex-end;
     /* background: lightgreen; */
 }

 /* ---------- logos ---------- */
 .logos {
     width: 100%;
     display: flex;
     justify-content: space-around;
     align-items: top;
     padding: 1mm 0;
     height: 30mm;
 }

 .logos div {
     width: 33%;
     display: flex;
     justify-content: center;
 }

 .logos img {
     max-height: 25mm;
     max-width: 95%;
 }

 .logos div:nth-child(3) img {
     margin-left: auto;
     padding-right: 2mm;
 }

 .logos div:nth-child(1) img {
     margin-right: auto;
     padding-left: 2mm;
 }

 .logos div:nth-child(2) {
     flex-direction: column;
     width: 50%;
 }

 .logos div:nth-child(2) div {
     width: 100%;
 }

 .logos div:nth-child(2) img {
     max-height: 15mm;
     width: 80%;
     align-self: center;
 }

 /* ---------- address + GSTIN ---------- */
 .address-gstin {
     width: 100%;
     margin: 0 auto;
     flex-direction: column;
 }

 .address {
     text-align: center;
     display: flex;
     flex-direction: column;
     font-size: 11px;
     height: 8mm;
     margin: 0;
 }

 .address-gstin p.gst {
     margin: 0;
     font-size: medium;
     text-align: center;
     font-weight: bold;
     padding-top: 2px;
 }

 /* ---------- title row ---------- */
 .title {
     width: 100%;
     height: 5mm;
     text-align: center;
     display: flex;
     justify-content: space-between;
     align-items: center;
     border-top: 1px solid black;
 }

 .title div {
     width: 33%;
     display: flex;
     justify-content: center;
     align-items: center;
 }

 .title p.original {
     margin-left: auto;
     font-size: xx-small;
     padding-right: 2mm;
 }

 .title p.debitnote {
     margin-right: auto;
     font-size: x-small;
     padding-left: 2mm;
 }

 .title p.taxinvoice {
     font-size: medium;
     font-weight: bold;
 }

 .labels {
     width: 100%;
     height: 5mm;
     font-size: 10px;
     font-weight: bold;
     background: #e2e2e2;
     border-top: 1px solid #000;
     display: flex;
     height: 5mm;
 }

 .labels div {
     width: 50%;
     display: flex;
     justify-content: center;
     align-items: center;
 }

 .labels div:nth-child(2) {
     border-left: 1px solid #000;
 }
 
 /* .labels div:nth-child(1) {
     border-right: 1px solid #000;
 } */

 .party {
     width: 100%;
     display: flex;
     height: 25mm;
     justify-content: center;
     align-items: center;
     line-height: 1.35;
     border-top: 1px solid #000;
 }

 .party div {
     width: 100%;

     /* padding-left: 1mm; */
 }


 .party div.ship,
 div.buyer {
     /* border:1px solid black; */
     height: 100%;
     width: 30%;
     padding: 1.1mm 0;
     display: flex;
     flex-direction: column;
     justify-content: space-between;
     border-left: 1px solid #000;
     /* border: 1px solid black; */
 }

 .party div.buyer {
     border-left: 0;
 }


 .party div.shipvalues,
 div.buyervalues {
     /* border:1px solid black; */
     height: 100%;
     width: 70%;
     padding: 1.1mm 0;
     display: flex;
     flex-direction: column;
     justify-content: space-between;
     /* border: 1px solid black; */

     /* align-items: space-between; */
     /* border-left: 1px solid #000; */
 }

 .party div.ship div,
 div.buyer div {
     display: flex;
     /* height: 100%; */
     width: 100%;
     /* justify-content: space-between; */
     flex-direction: column;
     justify-content: space-between;
     padding-left: 2mm;
     /* border:1px solid #000; */
 }

 .party div.shipvalues div,
 div.buyervalues div {
     display: flex;
     /* height: 100%; */
     width: 100%;
     /* justify-content: space-between; */
     flex-direction: column;
     justify-content: space-between;
     padding-left: 2mm;
     /* border:1px solid #000; */
 }

 .party div.ship div span,
 div.buyer div span {
     /* border:1px solid #000; */
     display: flex;
     justify-content: space-between;
 }

 /* ---------- invoice info (time, invoice no, ...) ---------- */
 .info {
     width: 100%;
     display: flex;
     height: 10mm;
     border-top: 1px solid #000;
     justify-content: space-between;
     align-items: center;
 }

 .info div.left,
 .info div.right {
     width: 100%;
     height: 100%;
     display: flex;
     justify-content: space-between;
     align-items: space-around;
 }

 .info div.left div,
 div.right div {
     width: 70%;
     display: flex;
     /* border:1px solid #000; */
     flex-direction: column;
     justify-content: space-around;
 }

 .info div.right {
     border-left: 1px solid #000;
 }

 .info div.right div.heads,
 div.left div.heads {
     width: 30%;
     display: flex;
     justify-content: space-between;
     /* border: 1px solid black; */

 }

 .info div.right div span,
 div.left div span {
     height: 100%;
     /* width:70%; */
     padding-left: 2mm;
     display: flex;
     justify-content: space-between;
     /* border: 1px solid black; */

 }

 .info div.heads {
     font-weight: bold;
 }





 /* ---------- items table ---------- */
 .items-wrap {
     height: 147mm;
 }

 /* ---------- base ---------- */
 table {
     width: 100%;
     border-collapse: collapse;
 }

 td,
 th {
     vertical-align: top;
     padding: 1px 5px;
     color: black !important;
 }

 .m {
     vertical-align: middle;
 }

 /* fixed height area */
 .items {
     height: 100%;
     width: 100%;
     table-layout: fixed;
     font-size: 9.5px;
 }

 .items thead {
     height: 5mm;
 }

 .items tbody {
     height: 105mm;
 }

 .items tfoot {
     height: 3mm;
 }

 .items th {
     border: 0.6px solid #000;
     padding: 0.5mm;
     font-size: 8.5px;
     font-weight: bold;
     text-align: center;
     vertical-align: middle;
 }
.items tbody tr:not(.fill){
    height:10.5mm;
}
 .items tbody td {
     border: 0.6px solid #000;
     border-top: none;
     border-bottom: none;
     padding: 2px;
 }

 .items tfoot td {
     border: 0.6px solid #000;
     padding: 2px;
     font-weight: bold;
     background: #e2e2e2;
 }

 tfoot tr td {
     border-left: none !important;
     border-right: none !important;
 }

 /* no outer left/right borders (frame already has them) */
 .items thead tr:first-child th:first-child,
 .items tbody td:first-child,
 .items tfoot td:first-child {
     border-left: none;
 }

 .items thead tr:first-child th:last-child,
 .items tbody td:last-child,
 .items tfoot td:last-child {
     border-right: none;
 }

 .items td:nth-child(2) {
     margin-left: 1mm;
 }

 /* column alignment */
 .items td:nth-child(1),
 .items td:nth-child(3),
 .items td:nth-child(4),
 .items td:nth-child(5),
 .items td:nth-child(6),
 .items td:nth-child(9) {
     text-align: center;
 }

 .items td:nth-child(7),
 .items td:nth-child(8),
 .items td:nth-child(10),
 .items td:nth-child(11),
 .items td:nth-child(12) {
     /* text-align: right; */
     text-align: center;

 }

 .items tbody td:nth-child(3) {
     font-size: 8.5px;
 }

 /* HSN code */
 .sub {
     font-size: 8.5px;
 }

 /* MRP line */
 .fill {
     height: 100%;
 }

 /* spacer row */

 /* ---------- footer ---------- */
 .footer {
     height: 85mm;
     width: 100%;
     /* border: 1px solid #000; */
     font-size: 10px;
 }

